    void save(const Order& order) override {
        std::cout << "Order saved to MySQL: " << order.getId() << std::endl;
    }
};

class OrderService {
public:
    explicit OrderService(std::shared_ptr<OrderRepository> repository)
        : repository_(std::move(repository)) {}

    void save(const Order& order) {
        repository_->save(order);
    }

private:
    std::shared_ptr<OrderRepository> repository_;
};

int main() {
    auto repository = std::make_shared<MySQLOrderRepository>();
    OrderService service(repository);
    service.save(Order("ORD-2002"));
    return 0;
}

